class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        long long total = 0, tank = 0;   // total: 净增量总和；tank: 从 start 出发的累计油量
        int start = 0;
        for (int i = 0; i < (int)gas.size(); ++i) {
            int diff = gas[i] - cost[i]; // 经过站 i 的净增量 = 加油 - 耗油
            total += diff;
            tank += diff;
            if (tank < 0) {              // 从 start 开到 i+1 半路断油
                start = i + 1;           // [start, i] 段内所有站都不能当起点，整段排除
                tank = 0;                // 以 i+1 为新起点重新累计
            }
        }
        // 净增量总和 < 0 必然绕不了一周；总量非负保证有解，且起点唯一
        return total < 0 ? -1 : start;
    }
};

