// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（加油站数）
//   第二行：n 个整数 gas（各站加油量）
//   第三行：n 个整数 cost（各站到下一站的耗油量）
// 输出格式：一行，可绕行一周的出发站编号；无解输出 -1
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> gas(n), cost(n);
    for (auto& g : gas) cin >> g;
    for (auto& c : cost) cin >> c;

    long long total = 0, tank = 0; // total: 净增量总和；tank: 从 start 出发的累计油量
    int start = 0;
    for (int i = 0; i < n; ++i) {
        int diff = gas[i] - cost[i];  // 净增量 = 加油 - 耗油
        total += diff;
        tank += diff;
        if (tank < 0) {            // 从 start 开到 i+1 半路断油
            start = i + 1;         // [start, i] 段内所有站都不能当起点，整段排除
            tank = 0;              // 以 i+1 为新起点重新累计
        }
    }
    // 总油量不够总消耗输出 -1；否则 start 即唯一合法起点
    cout << (total < 0 ? -1 : start) << endl;
    return 0;
}

