def candy_adjust(ratings) -> int:
    n = len(ratings)
    candies = [1] * n                # 每人先 1 颗
    changed = True
    while changed:                   # 反复整轮调整直到收敛
        changed = False
        for i in range(n):
            if i > 0 and ratings[i] > ratings[i - 1] and candies[i] <= candies[i - 1]:
                candies[i] = candies[i - 1] + 1   # 比左邻评分高，糖果也要更多
                changed = True
            if i < n - 1 and ratings[i] > ratings[i + 1] and candies[i] <= candies[i + 1]:
                candies[i] = candies[i + 1] + 1   # 比右邻评分高，糖果也要更多
                changed = True
    return sum(candies)

def candy_two_pass(ratings) -> int:
    n = len(ratings)
    candies = [1] * n                # 每人先发 1 颗，满足最低要求
    for i in range(1, n):            # 从左往右：只处理『评分比左邻高』的规则
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1
    for i in range(n - 2, -1, -1):   # 从右往左：补上『评分比右邻高』的规则
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)  # 取较大者，两条规则同时成立
    return sum(candies)

