class Solution {
    public int candy(int[] ratings) {
        int n = ratings.length;
        int[] candies = new int[n];
        Arrays.fill(candies, 1);         // 每人先发 1 颗，满足最低要求
        for (int i = 1; i < n; i++) {    // 从左往右：只处理『评分比左邻高』的规则
            if (ratings[i] > ratings[i - 1])
                candies[i] = candies[i - 1] + 1;
        }
        for (int i = n - 2; i >= 0; i--) {  // 从右往左：补上『评分比右邻高』的规则
            if (ratings[i] > ratings[i + 1])
                // 取较大者，两条规则同时成立；直接覆盖会破坏第一遍的递增链
                candies[i] = Math.max(candies[i], candies[i + 1] + 1);
        }
        // 两次遍历后每个位置都是同时满足两侧约束的最小值，总和即最少
        int total = 0;
        for (int c : candies) total += c;
        return total;
    }
}

