func candy(ratings []int) int {
	n := len(ratings)
	candies := make([]int, n)
	for i := range candies {
		candies[i] = 1 // 每人先发 1 颗，满足最低要求
	}
	for i := 1; i < n; i++ { // 从左往右：只处理『评分比左邻高』的规则
		if ratings[i] > ratings[i-1] {
			candies[i] = candies[i-1] + 1
		}
	}
	for i := n - 2; i >= 0; i-- { // 从右往左：补上『评分比右邻高』的规则
		// 取较大者，两条规则同时成立；直接覆盖会破坏第一遍的递增链
		if ratings[i] > ratings[i+1] && candies[i+1]+1 > candies[i] {
			candies[i] = candies[i+1] + 1
		}
	}
	total := 0
	for _, c := range candies { // 每个位置都是满足两侧约束的最小值，总和即最少
		total += c
	}
	return total
}
